from pathlib import Path
p=Path('build_report.py')
s=p.read_text(encoding='utf-8')
s=s.replace("g('sm_age.Age<30.n')", "g('sm_selfemp.Age<30.n')")
s=s.replace("g('sm_age.Age>=30.n')", "g('sm_selfemp.Age>=30.n')")
s=s.replace("They encode different decision policies.", "They encode different decision policies. That distinction matters because a score is not itself a policy. The analyst still chooses the cut point, decides which errors are acceptable, and determines whether a person receives review or an automatic outcome.")
s=s.replace("The important result is not that one reduced model is the truth.", "The important result is not that one reduced model is the truth; it is that the coefficient depends on the feature set and can move materially when a plausible predictor is removed.")
s=s.replace("A responsible audit should ask why this pocket exists and whether the same pattern appears in a new cohort before changing the deployment threshold.", "A responsible audit should ask why this pocket exists and whether the same pattern appears in a new cohort before changing the deployment threshold. I would also document the review criteria so the error analysis remains reproducible rather than anecdotal.")
p.write_text(s,encoding='utf-8')
print('Patched build_report.py subgroup-size paths and Q1/Q3/Q5 word counts')
